// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type BlueprintComparisonProps = Record<string, any>;

const Grid: React.FC<{ color: string; s: number }> = ({ color, s }) => {
  const { width, height } = useVideoConfig();
  const size = 80 * s;
  const cols = Math.ceil(width / size);
  const rows = Math.ceil(height / size);

  return (
    <svg width={width} height={height} style={{ position: "absolute", top: 0, left: 0 }}>
      {Array.from({ length: cols }).map((_, i) => (
        <line
          key={`c-${i}`}
          x1={i * size}
          y1={0}
          x2={i * size}
          y2={height}
          stroke={color}
          strokeWidth={1.5 * s}
        />
      ))}
      {Array.from({ length: rows }).map((_, i) => (
        <line
          key={`r-${i}`}
          x1={0}
          y1={i * size}
          x2={width}
          y2={i * size}
          stroke={color}
          strokeWidth={1.5 * s}
        />
      ))}
    </svg>
  );
};

const BlueprintComparison: React.FC<BlueprintComparisonProps> = ({
  backgroundColor = "#F9FAFB",
  transparentBackground = false,
  durationInSeconds = 10,
  gridColor = "#E5E7EB",
  lineColor = "#111827",
  smallBuildingFill = "#D1D5DB",
  largeBuildingFill = "#2563EB",
  textColor = "#111827",
  accentTextColor = "#FFFFFF",
}) => {
  const actualFrame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Scale frame progress dynamically if the duration is altered
  const frame = actualFrame * (10 / durationInSeconds);
  const s = width / 1080; // responsive scalar assuming 1080x1920 base

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // -- SCALES & POSITIONS --
  const scale = 5.0 * s;
  const w1 = 40 * scale;
  const h1 = 60 * scale;
  const w2 = 90 * scale;
  const h2 = 130 * scale;

  const gap = 160 * s;
  const rect1X = 135 * s;
  const rect2X = rect1X + w1 + gap;

  // Align both buildings on a shared baseline vertically
  const baselineY = height * 0.67;
  const rect1Y = baselineY - h1;
  const rect2Y = baselineY - h2;

  const offsetDim = 40 * s;

  // -- TIMING & ANIMATIONS --
  const gridOp = interpolate(frame, [0, 15], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

  // SMALL BUILDING (Frames 15-60)
  const b1DrawProg = interpolate(frame, [15, 45], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const b1DimLine = interpolate(frame, [45, 55], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const b1DimTick = interpolate(frame, [50, 60], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const w1Count = Math.round(interpolate(frame, [50, 60], [0, 40], { extrapolateRight: "clamp", extrapolateLeft: "clamp" }));
  const h1Count = Math.round(interpolate(frame, [50, 60], [0, 60], { extrapolateRight: "clamp", extrapolateLeft: "clamp" }));

  // LARGE BUILDING (Frames 90-165)
  const b2DrawProg = interpolate(frame, [90, 135], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const b2DimLine = interpolate(frame, [135, 145], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const b2DimTick = interpolate(frame, [140, 150], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const w2Count = Math.round(interpolate(frame, [145, 165], [0, 90], { extrapolateRight: "clamp", extrapolateLeft: "clamp" }));
  const h2Count = Math.round(interpolate(frame, [145, 165], [0, 130], { extrapolateRight: "clamp", extrapolateLeft: "clamp" }));

  // REVEALS (Fills, Texts, Callout)
  const fillsOp = interpolate(frame, [165, 195], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const textOp = interpolate(frame, [195, 215], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const textYOffset = interpolate(frame, [195, 215], [20, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  
  const calloutStartActualFrame = 195 / (10 / durationInSeconds);
  const calloutScale = spring({
    frame: actualFrame - calloutStartActualFrame,
    fps,
    config: { damping: 14 },
  });
  const connectionOp = interpolate(frame, [200, 220], [0, 0.4], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

  const perimeter1 = (w1 + h1) * 2;
  const perimeter2 = (w2 + h2) * 2;

  // -- RENDER HELPERS --
  const renderDimension = (opts: {
    x: number; y: number; length: number; orientation: "top" | "left" | "right";
    lineProgress: number; tickOp: number; count: number;
  }) => {
    const { x, y, length, orientation, lineProgress, tickOp, count } = opts;
    if (lineProgress === 0) return null;

    const isHoriz = orientation === "top";
    const endX = isHoriz ? x + length : x;
    const endY = isHoriz ? y : y + length;
    const strokeW = 2 * s;
    const tickLen = 6 * s;
    const textOffset = 20 * s;

    let textX, textY, rotation = 0;
    if (orientation === "top") {
      textX = x + length / 2; textY = y - textOffset;
    } else if (orientation === "left") {
      textX = x - textOffset - 5 * s; textY = y + length / 2; rotation = -90;
    } else {
      textX = x + textOffset + 5 * s; textY = y + length / 2; rotation = -90;
    }

    return (
      <g>
        <line
          x1={x} y1={y} x2={endX} y2={endY}
          stroke={lineColor} strokeWidth={strokeW}
          strokeDasharray={length} strokeDashoffset={length - length * lineProgress}
        />
        <line x1={x - (isHoriz ? 0 : tickLen)} y1={y - (isHoriz ? tickLen : 0)} x2={x + (isHoriz ? 0 : tickLen)} y2={y + (isHoriz ? tickLen : 0)} stroke={lineColor} strokeWidth={strokeW} style={{ opacity: tickOp }} />
        <line x1={endX - (isHoriz ? 0 : tickLen)} y1={endY - (isHoriz ? tickLen : 0)} x2={endX + (isHoriz ? 0 : tickLen)} y2={endY + (isHoriz ? tickLen : 0)} stroke={lineColor} strokeWidth={strokeW} style={{ opacity: tickOp }} />
        <text
          x={textX} y={textY}
          fill={textColor} fontFamily={interFamily} fontSize={26 * s} fontWeight={600}
          textAnchor="middle" alignmentBaseline="middle"
          style={{ opacity: tickOp }}
          transform={rotation ? `rotate(${rotation} ${textX} ${textY})` : undefined}
        >
          {count}
        </text>
      </g>
    );
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      {/* Background Grid */}
      <div style={{ opacity: gridOp, position: "absolute", inset: 0 }}>
        <Grid color={gridColor} s={s} />
      </div>

      <svg width={width} height={height} style={{ overflow: "visible" }}>
        
        {/* Soft Fills */}
        <rect x={rect1X} y={rect1Y} width={w1} height={h1} fill={smallBuildingFill} style={{ opacity: fillsOp, transition: "none" }} />
        <rect x={rect2X} y={rect2Y} width={w2} height={h2} fill={largeBuildingFill} style={{ opacity: fillsOp, transition: "none" }} />

        {/* Building Outlines */}
        <rect
          x={rect1X} y={rect1Y} width={w1} height={h1}
          fill="none" stroke={lineColor} strokeWidth={4 * s} strokeLinecap="square"
          strokeDasharray={perimeter1} strokeDashoffset={perimeter1 - perimeter1 * b1DrawProg}
          style={{ transition: "none" }}
        />
        <rect
          x={rect2X} y={rect2Y} width={w2} height={h2}
          fill="none" stroke={lineColor} strokeWidth={4 * s} strokeLinecap="square"
          strokeDasharray={perimeter2} strokeDashoffset={perimeter2 - perimeter2 * b2DrawProg}
          style={{ transition: "none" }}
        />

        {/* Dimensions - Small */}
        {renderDimension({ x: rect1X, y: rect1Y - offsetDim, length: w1, orientation: "top", lineProgress: b1DimLine, tickOp: b1DimTick, count: w1Count })}
        {renderDimension({ x: rect1X - offsetDim, y: rect1Y, length: h1, orientation: "left", lineProgress: b1DimLine, tickOp: b1DimTick, count: h1Count })}

        {/* Dimensions - Large */}
        {renderDimension({ x: rect2X, y: rect2Y - offsetDim, length: w2, orientation: "top", lineProgress: b2DimLine, tickOp: b2DimTick, count: w2Count })}
        {renderDimension({ x: rect2X + w2 + offsetDim, y: rect2Y, length: h2, orientation: "right", lineProgress: b2DimLine, tickOp: b2DimTick, count: h2Count })}

        {/* Dotted Connection Line */}
        <line
          x1={rect1X + w1} y1={baselineY - h1 / 2}
          x2={rect2X} y2={baselineY - h1 / 2}
          stroke={lineColor} strokeWidth={2 * s} strokeDasharray={`${6 * s} ${6 * s}`}
          style={{ opacity: connectionOp, transition: "none" }}
        />

        {/* Square Footage Texts */}
        <text
          x={rect1X + w1 / 2} y={baselineY + 60 * s + textYOffset * s}
          fill={textColor} fontFamily={interFamily} fontSize={32 * s} fontWeight={500}
          textAnchor="middle" alignmentBaseline="middle"
          style={{ opacity: textOp, transition: "none" }}
        >
          2,400 sq ft
        </text>
        <text
          x={rect2X + w2 / 2} y={baselineY + 60 * s + textYOffset * s}
          fill={textColor} fontFamily={interFamily} fontSize={32 * s} fontWeight={500}
          textAnchor="middle" alignmentBaseline="middle"
          style={{ opacity: textOp, transition: "none" }}
        >
          11,700 sq ft
        </text>

        {/* Floating Callout Badge */}
        <g transform={`translate(${rect1X + w1 + gap / 2}, ${baselineY - h1 / 2}) scale(${calloutScale})`}>
          <rect
            x={-80 * s} y={-22 * s} width={160 * s} height={44 * s} rx={22 * s}
            fill={largeBuildingFill}
            style={{ transition: "none" }}
          />
          <text
            y={2 * s}
            fill={accentTextColor} fontFamily={interFamily} fontSize={20 * s} fontWeight={700}
            textAnchor="middle" alignmentBaseline="middle"
            style={{ transition: "none" }}
          >
            ~4.9x larger
          </text>
        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default BlueprintComparison;